//---------------------------------------------------------------------------//
// Unit tests for tools/lina/line
// Initial implementation generated by GitHub CoPilot (GPT-4.1)
//---------------------------------------------------------------------------//
#include "tools/lina/line"

#include "tools/lina/vec"
#include <gtest/gtest.h>

namespace tools
{
//---------------------------------------------------------------------------//
// TEST FIXTURES
//---------------------------------------------------------------------------//
// Helpers for clarity. Tools doesn't provide these aliases as they're never
// actually used, but we want to test them.
using vec3d = vec3<double>;
using line3d = line<double>;

//---------------------------------------------------------------------------//
TEST(Line, ConstructionAndAccessFloat)
{
  vec3f p1(1.0f, 2.0f, 3.0f);
  vec3f p2(4.0f, 6.0f, 8.0f);
  line3f l(p1, p2);
  EXPECT_FLOAT_EQ(l.position().x(), 1.0f);
  EXPECT_FLOAT_EQ(l.position().y(), 2.0f);
  EXPECT_FLOAT_EQ(l.position().z(), 3.0f);

  // Direction should be normalized vector from p1 to p2
  vec3f expected_dir = p2 - p1;
  expected_dir.normalize();
  EXPECT_FLOAT_EQ(l.direction().x(), expected_dir.x());
  EXPECT_FLOAT_EQ(l.direction().y(), expected_dir.y());
  EXPECT_FLOAT_EQ(l.direction().z(), expected_dir.z());
}

TEST(Line, ConstructionAndAccessDouble)
{
  vec3d p1(1.0, 2.0, 3.0);
  vec3d p2(4.0, 6.0, 8.0);
  line3d l(p1, p2);
  EXPECT_DOUBLE_EQ(l.position().x(), 1.0);
  EXPECT_DOUBLE_EQ(l.position().y(), 2.0);
  EXPECT_DOUBLE_EQ(l.position().z(), 3.0);

  vec3d expected_dir = p2 - p1;
  expected_dir.normalize();
  EXPECT_DOUBLE_EQ(l.direction().x(), expected_dir.x());
  EXPECT_DOUBLE_EQ(l.direction().y(), expected_dir.y());
  EXPECT_DOUBLE_EQ(l.direction().z(), expected_dir.z());
}

TEST(Line, DirectionIsNormalizedFloat)
{
  vec3f p1(0.0f, 0.0f, 0.0f);
  vec3f p2(0.0f, 3.0f, 4.0f);
  line3f l(p1, p2);
  float len =
    std::sqrt(l.direction().x() * l.direction().x() + l.direction().y() * l.direction().y()
              + l.direction().z() * l.direction().z());
  EXPECT_NEAR(len, 1.0f, 1e-6f);
}

TEST(Line, DirectionIsNormalizedDouble)
{
  vec3d p1(0.0, 0.0, 0.0);
  vec3d p2(0.0, 3.0, 4.0);
  line3d l(p1, p2);
  double len =
    std::sqrt(l.direction().x() * l.direction().x() + l.direction().y() * l.direction().y()
              + l.direction().z() * l.direction().z());
  EXPECT_NEAR(len, 1.0, 1e-12);
}

TEST(Line, DefaultConstructorIsEmpty)
{
  line3f lf;
  EXPECT_FLOAT_EQ(lf.position().x(), 0.0f);
  EXPECT_FLOAT_EQ(lf.position().y(), 0.0f);
  EXPECT_FLOAT_EQ(lf.position().z(), 0.0f);
  EXPECT_FLOAT_EQ(lf.direction().x(), 0.0f);
  EXPECT_FLOAT_EQ(lf.direction().y(), 0.0f);
  EXPECT_FLOAT_EQ(lf.direction().z(), 0.0f);

  line3d ld;
  EXPECT_DOUBLE_EQ(ld.position().x(), 0.0);
  EXPECT_DOUBLE_EQ(ld.position().y(), 0.0);
  EXPECT_DOUBLE_EQ(ld.position().z(), 0.0);
  EXPECT_DOUBLE_EQ(ld.direction().x(), 0.0);
  EXPECT_DOUBLE_EQ(ld.direction().y(), 0.0);
  EXPECT_DOUBLE_EQ(ld.direction().z(), 0.0);
}

//---------------------------------------------------------------------------//
}  // namespace tools
